import{_ as a,o,c as d,a2 as t}from"./chunks/framework.BWuWLRhz.js";const m=JSON.parse('{"title":"Servicios del host","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/dev-guide/sdk/services.md","filePath":"es-ES/dev-guide/sdk/services.md","lastUpdated":1785214938000}'),r={name:"es-ES/dev-guide/sdk/services.md"};function c(i,e,s,n,l,u){return o(),d("div",null,[...e[0]||(e[0]=[t('<h1 id="servicios-del-host" tabindex="-1">Servicios del host <a class="header-anchor" href="#servicios-del-host" aria-label="Permalink to &quot;Servicios del host&quot;">​</a></h1><p>Servicios estáticos en <code>PluginSdk.Services</code> que exponen funcionalidad de la aplicación host a los plugins — cada uno es una fina clase estática que envuelve un delegado que el host conecta al iniciarse, de modo que los plugins los llaman de la misma manera sin importar qué haya funcionando por debajo.</p><table tabindex="0"><thead><tr><th>Servicio</th><th>Propósito</th></tr></thead><tbody><tr><td><code>FuzzyMatchService</code></td><td><code>IsMatch(pattern, text)</code> — si <code>text</code> (o uno de sus alias) coincide con un <code>pattern</code> de sintaxis fzf, usando exactamente la misma coincidencia que emplea la propia búsqueda del host; <code>GetHighlightMask(text, query)</code> — la máscara de resaltado por carácter para ese par, usando los mismos niveles de reserva literal/difuso/alias (incluido el pinyin CJK) con los que el host resalta sus propios resultados, de modo que los resultados de un plugin se resalten de forma coherente en lugar de solo gestionar una coincidencia de subcadena literal.</td></tr><tr><td><code>TranslationService</code></td><td><code>Get(key)</code> / <code>Format(key, args)</code> para búsquedas en tiempo de ejecución contra el idioma activo; <code>LoadEmbeddedTranslations(assembly, cultureKey, typeName)</code> para cargar las propias traducciones JSON incrustadas de un plugin; <code>GetSupportedCultures(assembly)</code>; <code>GetCurrentCulture()</code> — el idioma de interfaz actualmente seleccionado por la aplicación (por ejemplo, <code>&quot;zh-CN&quot;</code>), un ajuste de usuario independiente de la configuración regional del sistema operativo. Recurre a esto solo cuando necesites el propio código de cultura en bruto (por ejemplo, para ponerlo en una cabecera HTTP <code>Accept-Language</code> o elegir el idioma de destino de una API de traducción) — <code>CultureInfo.CurrentUICulture</code> refleja la configuración regional del sistema operativo, no este ajuste, y discrepará en silencio con él siempre que el idioma de Windows del usuario y el idioma dentro de la app difieran.</td></tr><tr><td><code>IconService</code></td><td><code>GetIcon(path, isDir)</code> y <code>GetThumbnail(path, size)</code> — extracción de icono/miniatura del shell con caché, de modo que un plugin nunca tenga que invocar directamente las API de iconos de Windows.</td></tr><tr><td><code>FavoritesService</code></td><td><code>GetFavorites()</code> — acceso de solo lectura a la lista de <a href="./../../user-guide/settings/favorites.html">Favoritos</a> del usuario (<code>FavoriteItem</code>: Name, Path).</td></tr><tr><td><code>HistoryService</code></td><td><code>GetHistoryEntries()</code> — cada entrada registrada de <a href="./../../user-guide/settings/history.html">Historial</a>, con la abierta más recientemente primero, como <code>HistoryEntry { Keyword, Path, Kind, Time }</code> (<code>Kind</code> es un <code>HistoryEntryKind</code>: <code>File</code> / <code>Folder</code> / <code>Application</code>; <code>Keyword</code> es el texto de búsqueda que llevó hasta ella, vacío si se abrió directamente desde una pestaña del Panel de Inicio sin escribir ninguna consulta; <code>Time</code> son segundos Unix). Cada ruta aparece como máximo una vez, bajo cualquiera que sea la palabra clave que más recientemente haya llevado hasta ella.</td></tr><tr><td><code>FileMetadataService</code></td><td><code>GetMetadataAsync(paths)</code> — consulta por lotes de Size/Created/Modified/Accessed (<a href="./abstractions.html#filemetadata"><code>FileMetadata</code></a>) para una ruta que <strong>no</strong> sea ya uno de tus resultados actuales — cada <code>ISearchResult</code> ya lleva esto consigo mediante su propia propiedad <code>Metadata</code> sin coste alguno (ver <a href="./abstractions.html#isearchresult">Abstracciones</a>), así que recurre a este servicio solo para rutas que hayas obtenido de otra manera (por ejemplo, desde tu propia configuración).</td></tr><tr><td><code>DirectoryIndexerService</code></td><td><code>RegisterDirectory(pluginId, path, recursive, filterPattern)</code> / <code>UnregisterDirectories(pluginId)</code> / <code>SearchDirectoriesAsync(pluginId, query, token)</code> / <code>NotifyDirectoryChanged(pluginId)</code> — permite que un plugin registre sus propios directorios para indexación y monitorización USN en segundo plano, sin reimplementar esa maquinaria.</td></tr><tr><td><code>PluginSettingsService</code></td><td><code>GetSetting&lt;T&gt;(pluginId, key, defaultValue)</code> — acceso de solo lectura a la configuración persistida propia de un plugin en el almacén de configuración del host. Recurre a tres niveles en cascada: el valor persistido si el usuario alguna vez guardó uno, luego el propio <code>DefaultValue</code> de tu esquema <code>IConfigurable</code> para ese campo si no se persistió nada, y por último el argumento <code>defaultValue</code> que hayas pasado como último recurso — de modo que un valor predeterminado declarado en el esquema es la única fuente de verdad y no necesita una segunda copia codificada a mano en tu punto de llamada. Si guardas en caché un ajuste en lugar de volver a leerlo en cada llamada, suscríbete al evento <code>SettingChanged(pluginId, key)</code> y descarta tu caché cuando se dispare para tu plugin — el host lo lanza justo después de guardar en la página de configuración, que es el único punto fiable para invalidar la caché (una comprobación por pulsación de tecla o por sondeo no verá un cambio hasta lo que sea que lo desencadene coincidentemente la próxima vez, o nunca).</td></tr><tr><td><code>SearchRefreshService</code></td><td><code>RefreshIfMatches(queryMatches)</code> — para un <code>IInstantResultProvider</code> cuyos datos llegan de forma asíncrona (ver <a href="./core-search-actions.html#iinstantresultprovider"><code>IInstantResultProvider</code></a>): una vez que tu obtención en segundo plano termina y has guardado el resultado en caché, llama a esto con un predicado sobre el texto de consulta actual de una búsqueda, y el host vuelve a ejecutar toda búsqueda activa cuya consulta coincida con ese predicado, de modo que el resultado ahora en caché realmente aparezca sin que el usuario necesite volver a escribir nada.</td></tr><tr><td><code>Logger</code></td><td><code>Log(message, level = LogLevel.Info)</code> — escribe en el archivo de registro de la App, visible en <strong>Configuración → Estado del Servicio → App</strong> exactamente igual que las propias líneas de registro del host.</td></tr><tr><td><code>PluginPromptService</code></td><td><code>Prompt(title, fields, initialValues?)</code> — muestra un pequeño modal solicitando los valores de <a href="./abstractions.html#iconfigurable"><code>PluginConfigField</code></a> indicados (el mismo esquema/renderizado de campos que usa el diálogo Configurar de <code>IConfigurable</code>), precargado a partir de <code>initialValues</code> (emparejado por <code>Key</code>) o del propio <code>DefaultValue</code> de cada campo. Devuelve los valores introducidos, indexados por <code>Key</code> de campo, o <code>null</code> si el usuario canceló — estos valores nunca se leen de la configuración persistida real del plugin ni se escriben en ella, así que es seguro reutilizar el esquema de un campo de configuración únicamente para una entrada puntual (por ejemplo, &quot;ponle un nombre antes de añadirlo&quot;) sin tocar el ajuste real que hay detrás.</td></tr></tbody></table><p><code>LogLevel</code> es <code>Error</code> / <code>Warn</code> / <code>Info</code> / <code>Debug</code>, coincidiendo con el filtro de nivel del <a href="./../../user-guide/settings/service-status.html">visor de registros de Estado del Servicio</a>.</p>',4)])])}const g=a(r,[["render",c]]);export{m as __pageData,g as default};
